/*
 * A363216  Even powerful numbers that are not prime powers.
 * https://oeis.org/A363216
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th even powerful number that is not a prime power.
 *            (a powerful number is one with all prime exponents ≥ 2). The
 *            sequence is generated by enumerating all a^2·b^3, filtering
 *            those that are even and have at least two distinct prime factors
 * Range:     u8 n <= 8, u16 n <= 290, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Standard headers */
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/*--------------------------------------------------------------------
 * Helper: comparison for qsort on uint64_t
 *--------------------------------------------------------------------*/
static int cmp_uint64(const void *p1, const void *p2)
{
    const uint64_t a = *(const uint64_t *)p1;
    const uint64_t b = *(const uint64_t *)p2;
    return (a < b) ? -1 : (a > b) ? 1 : 0;
}

/*--------------------------------------------------------------------
 * Generate all primes ≤ limit using the Sieve of Eratosthenes.
 * The result is stored in a dynamically allocated array with
 * the number of primes returned in `cnt_out`.
 *--------------------------------------------------------------------*/
static void sieve_primes(uint32_t limit, uint32_t **primes_out, size_t *cnt_out)
{
    bool *is_composite = (bool *)calloc(limit + 1, sizeof(bool));
    if (!is_composite) return; /* out of memory; caller will fail gracefully */

    /* Count primes first */
    size_t tmp_cnt = 0;
    for (uint32_t i = 2; i <= limit; ++i)
        if (!is_composite[i]) ++tmp_cnt;

    uint32_t *pr = (uint32_t *)malloc(tmp_cnt * sizeof(uint32_t));
    if (!pr) { free(is_composite); return; }

    size_t idx = 0;
    for (uint32_t i = 2; i <= limit; ++i) {
        if (is_composite[i]) continue;
        pr[idx++] = i;
        if ((uint64_t)i * i <= limit) {
            for (uint32_t j = i * i; j <= limit; j += i)
                is_composite[j] = true;
        }
    }

    free(is_composite);
    *primes_out = pr;
    *cnt_out    = tmp_cnt;
}

/*--------------------------------------------------------------------
 * Count distinct prime factors of n using a list of primes.
 * Returns the number of distinct prime factors (≥ 0).
 *--------------------------------------------------------------------*/
static int distinct_prime_factor_count(uint64_t n, const uint32_t *primes, size_t prime_cnt)
{
    int count = 0;
    uint64_t temp = n;
    for (size_t i = 0; i < prime_cnt && (uint64_t)primes[i] * primes[i] <= temp; ++i) {
        uint32_t p = primes[i];
        if (temp % p == 0) {
            ++count;
            while (temp % p == 0) temp /= p;
            if (count > 1) return count; /* early exit */
        }
    }
    if (temp > 1) ++count; /* remaining prime factor > sqrt(n) */
    return count;
}

/*--------------------------------------------------------------------
 * Build the sequence of even powerful numbers not prime powers
 * up to the given limit (inclusive).  The generated numbers are
 * sorted increasingly and stored in a dynamically allocated array
 * pointed to by `seq_out`.  The function returns the number of
 * elements stored.  On failure, *seq_out is NULL and size is 0.
 *--------------------------------------------------------------------*/
static size_t build_sequence(uint64_t limit, uint64_t **seq_out)
{
    /* First, generate all a^2 · b^3 ≤ limit */
    uint64_t *candidates = (uint64_t *)malloc(8 * sizeof(uint64_t));
    if (!candidates) { *seq_out = NULL; return 0; }
    size_t cand_cap = 8, cand_len = 0;

    for (uint64_t a = 1; a <= limit / a; ++a) {           /* a*a ≤ limit, no overflow */
        uint64_t a_sq = a * a;
        for (uint64_t b = 1; ; ++b) {
            /* b*b*b ≤ limit and no overflow */
            if (b > limit / (b * b)) break; /* if b*b > limit/b then b^3 > limit */
            uint64_t b_sq  = b * b;
            uint64_t b_cub = b_sq * b;

            if (a_sq > limit / b_cub) break;
            uint64_t val = a_sq * b_cub;
            /* Store the candidate for later filtering */
            if (cand_len == cand_cap) {
                cand_cap *= 2;
                uint64_t *tmp = (uint64_t *)realloc(candidates, cand_cap * sizeof(uint64_t));
                if (!tmp) { free(candidates); *seq_out = NULL; return 0; }
                candidates = tmp;
            }
            candidates[cand_len++] = val;
        }
    }

    /* Sort candidates to enable duplicate removal */
    qsort(candidates, cand_len, sizeof(uint64_t), cmp_uint64);

    /* Build prime list up to sqrt(limit) */
    uint32_t prime_limit = 0;
    /* integer sqrt: find the largest x such that x*x ≤ limit */
    uint64_t lo = 0, hi = UINT32_MAX;
    while (lo <= hi) {
        uint64_t mid = (lo + hi) >> 1;
        if (mid > limit / mid) hi = mid - 1;
        else {
            prime_limit = (uint32_t)mid;
            lo = mid + 1;
        }
    }

    uint32_t *primes = NULL;
    size_t prime_cnt = 0;
    sieve_primes(prime_limit, &primes, &prime_cnt);

    /* Filter: even, and having at least two distinct prime factors */
    uint64_t *filtered = (uint64_t *)malloc(cand_len * sizeof(uint64_t));
    if (!filtered) { free(candidates); free(primes); *seq_out = NULL; return 0; }
    size_t filt_len = 0;

    for (size_t i = 0; i < cand_len; ++i) {
        uint64_t v = candidates[i];
        if ((v & 1) != 0) continue;                 /* must be even */
        if (distinct_prime_factor_count(v, primes, prime_cnt) > 1)
            filtered[filt_len++] = v;
    }

    free(candidates);
    free(primes);

    /* Deduplicate the filtered list */
    uint64_t *unique = (uint64_t *)malloc(filt_len * sizeof(uint64_t));
    if (!unique) { free(filtered); *seq_out = NULL; return 0; }
    size_t uniq_len = 0;

    if (filt_len > 0) {
        unique[0] = filtered[0];
        uniq_len  = 1;
        for (size_t i = 1; i < filt_len; ++i) {
            if (filtered[i] != filtered[i-1]) {
                unique[uniq_len++] = filtered[i];
            }
        }
    }

    free(filtered);

    *seq_out = unique;
    return uniq_len;
}

/*--------------------------------------------------------------------
 * Static state: the sequence array, its length, and the current
 * generation limit.  The array holds values as uint64_t that are
 * converted to seq_t upon request.  It is rebuilt lazily and
 * expanded by doubling the limit until we have enough terms.
 *--------------------------------------------------------------------*/
static uint64_t *seq64          = NULL;
static size_t    seq64_len      = 0;
static uint64_t  current_limit  = 1024;    /* initial rough limit */

/* Ensure that seq64 contains at least n elements (n ≥ 1). */
static void ensure_length(idx_t n)
{
    if (seq64_len >= (size_t)n) return;

    /* Rebuild with increasing limits until enough terms are available */
    while (seq64_len < (size_t)n) {
        /* Double the limit (but avoid overflow). */
        if (current_limit > UINT64_MAX / 2) current_limit = UINT64_MAX;
        else current_limit *= 2;

        /* Free previous array if any */
        free(seq64);

        /* Generate sequence up to the new limit */
        seq64_len = build_sequence(current_limit, &seq64);
        if (seq64_len == 0) break;  /* cannot generate further (unlikely) */
    }
}

/*--------------------------------------------------------------------
 * Required function.
 *--------------------------------------------------------------------*/
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* safety: offset is 1 */
    ensure_length(n);
    return (seq_t)seq64[n - 1];
}
